import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import * as React from 'react'

import {useIsAutodetectTimeZone} from '../../../hooks/useIsAutodetectTimeZone'
import {displayDate} from '../../../utils/dateTimeUtils'
import BuildAgentLink from '../AgentLink/BuildAgentLink.container'
import Plugin from '../Plugin/Plugin'

import type {Props} from './AgentInfo.types'
import AgentPoolLink from './AgentPoolLink/AgentPoolLink.container'

import styles from './AgentInfo.module.css'

function AgentInfo({
  className,
  valueClassName,
  linkClassName,
  buildId,
  withLabel,
  withAgent,
  withPool,
  withTooltip,
  detachedFromAgent,
  finishOnAgentDate,
  secondary,
  isQueued,
  afterName,
}: Props) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  if (!withAgent) {
    return null
  }

  const classes = classNames(className, styles.wrapper)

  const value = (
    <>
      <div className={classNames(styles.value, valueClassName)}>
        <BuildAgentLink
          className={classNames(linkClassName, styles.agent)}
          buildId={buildId}
          secondary={secondary}
          withTooltip={withTooltip}
          afterName={afterName}
        />
        {withPool && (
          <>
            {' — '}
            <AgentPoolLink className={styles.agentPool} buildId={buildId} secondary={secondary} />
          </>
        )}
      </div>
      <Plugin inline placeId={PlaceId.SAKURA_AFTER_AGENT_INFO} buildId={buildId} />
    </>
  )

  return withLabel ? (
    <tr className={classes}>
      <th>
        {isQueued ? 'Planned agent' : detachedFromAgent ? 'Detached from\u00a0agent' : 'Agent'}
      </th>
      <td>
        {value}
        {detachedFromAgent && finishOnAgentDate != null
          ? ` on ${displayDate(finishOnAgentDate, isAutodetectTimeZone, true)}`
          : ''}
      </td>
    </tr>
  ) : (
    <div className={classes}>{value}</div>
  )
}

export default React.memo(AgentInfo)
